<script setup>
import {computed,defineAsyncComponent,onBeforeUnmount,onMounted,ref} from 'vue'
import {api,thumb,waitJob} from '../api'
import JobProgress from './JobProgress.vue'
const ImageComparison=defineAsyncComponent(()=>import('./ImageComparison.vue'))
const VersionPanel=defineAsyncComponent(()=>import('./VersionPanel.vue'))
const props=defineProps({profile:Object}),emit=defineEmits(['changed'])
const stages={original:'原始图',reference:'参考图',sketch:'草稿',lineart:'线稿',color:'上色版',modification:'修改版','three-view':'三视图',expression:'表情',clothing:'服装',hatching:'排线练习'}
const list=ref({items:[],total:0}),offset=ref(0),current=ref(null),form=ref({title:'',notes:''}),newTitle=ref(''),entry=ref({reference_id:'',stage:'reference',notes:'',learned_on:new Date().toLocaleDateString('sv-SE')}),editing=ref(null),entriesOffset=ref(0),busy=ref(false),error=ref(''),source=ref(''),operation=ref('lineart'),format=ref('png'),background=ref('white'),addToStudy=ref(true),job=ref(null),history=ref([]),left=ref(''),right=ref(''),showCompare=ref(false),showHistory=ref(false)
const lifecycle=new AbortController();onBeforeUnmount(()=>lifecycle.abort())
const resources=computed(()=>props.profile.references.filter(r=>r.kind==='asset'&&r.status==='ok'))
const images=computed(()=>resources.value.filter(r=>r.is_image))
const studyImages=computed(()=>current.value?.entries.filter(r=>r.is_image&&r.status==='ok')||[])
const visible=computed(()=>current.value?.entries.slice(entriesOffset.value,entriesOffset.value+50)||[])
const dirty=computed(()=>current.value&&(form.value.title!==current.value.title||form.value.notes!==current.value.notes))
const chosen=computed(()=>source.value.startsWith('oc:')?images.value.find(r=>r.id===source.value.slice(3)):studyImages.value.find(r=>r.id===source.value.slice(6)))
const original=computed(()=>!chosen.value?'':source.value.startsWith('oc:')?`/api/oc/${props.profile.id}/images/${chosen.value.id}/file?download=true`:`/api/oc-studies/${current.value.id}/entries/${chosen.value.id}/file?download=true`)
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){if(!lifecycle.signal.aborted)error.value=e.message}finally{if(!lifecycle.signal.aborted)busy.value=false}}
function bind(s){current.value=s;form.value={title:s.title,notes:s.notes};editing.value=null;entriesOffset.value=0;showCompare.value=false}
async function load(){list.value=await api.get(`/api/oc/${props.profile.id}/studies`,{offset:offset.value});history.value=(await api.get('/api/jobs',{kind:'oc-raster'})).filter(j=>j.result?.profile_id===props.profile.id).slice(0,20)}
async function select(id){if(!id){current.value=null;return}bind(await api.get(`/api/oc-studies/${id}`));source.value=images.value[0]?'oc:'+images.value[0].id:''}
onMounted(()=>run(async()=>{await load();if(list.value.items[0])await select(list.value.items[0].id);else if(images.value[0])source.value='oc:'+images.value[0].id}))
async function create(){const s=await api.post(`/api/oc/${props.profile.id}/studies`,{title:newTitle.value});bind(s);newTitle.value='';await load()}
async function save(){bind(await api.put(`/api/oc-studies/${current.value.id}`,{...form.value,expected_version:current.value.version}));await load()}
async function append(){bind(await api.post(`/api/oc-studies/${current.value.id}/entries`,{...entry.value,expected_version:current.value.version}))}
function edit(e){editing.value={id:e.id,stage:e.stage,notes:e.learning_notes,learned_on:e.learned_on}}
async function saveEntry(){const {id,...body}=editing.value;bind(await api.patch(`/api/oc-studies/${current.value.id}/entries/${id}`,{...body,expected_version:current.value.version}))}
async function remove(e){bind(await api.del(`/api/oc-studies/${current.value.id}/entries/${e.id}?expected_version=${current.value.version}`))}
async function process(){const body={operation:operation.value,format:format.value,background:background.value,save_to_study:addToStudy.value,expected_version:props.profile.version};if(source.value.startsWith('entry:')){body.study_id=current.value.id;body.entry_id=source.value.slice(6)}else{body.reference_id=source.value.slice(3);if(addToStudy.value&&current.value&&operation.value==='lineart')body.study_id=current.value.id}job.value=await api.post(`/api/oc/${props.profile.id}/render`,body);await waitJob(job.value.id,j=>job.value=j,500,lifecycle.signal);if(lifecycle.signal.aborted)return;emit('changed');if(current.value)bind(await api.get(`/api/oc-studies/${current.value.id}`));await load()}
async function resume(j){job.value=j;if(['queued','running'].includes(j.status)){await waitJob(j.id,v=>job.value=v,700,lifecycle.signal);if(lifecycle.signal.aborted)return;emit('changed');await load()}}
async function retry(j){const r=j.result.recipe;if(!r)return;if(r.study_id)await select(r.study_id);source.value=r.entry_id?'entry:'+r.entry_id:'oc:'+r.reference_id;operation.value=r.operation;format.value=r.format;background.value=r.background}
const studyMedia=id=>`/api/oc-studies/${current.value.id}/entries/${id}/file`
</script>
<template><div class="grid">
<p v-if="error" role="alert" class="notice">{{error}}</p><p v-if="dirty" class="notice">学习集说明尚未保存；请先保存或放弃修改，再操作练习记录。</p>
<section class="card grid"><h2>绘画学习收藏集</h2><p class="small muted">原图、草稿、线稿、上色和排线练习共用现有素材，不重复复制。每次修改保留版本；移除练习记录保留素材和收藏集引用。</p><form class="row" @submit.prevent="run(create)"><input v-model="newTitle" aria-label="新学习集名称" placeholder="新练习集名称" maxlength="200"/><button :disabled="busy||dirty||!newTitle.trim()">创建学习集</button></form><label class="field">当前学习集<select :value="current?.id||''" :disabled="busy||dirty" @change="run(()=>select(Number($event.target.value)))"><option value="">选择学习集</option><option v-for="s in list.items" :key="s.id" :value="s.id">{{s.title}} · #{{s.id}}</option></select></label><nav class="row"><button :disabled="busy||dirty||!offset" @click="offset-=30;run(load)">上一页学习集</button><span>{{list.total}}集</span><button :disabled="busy||dirty||offset+30>=list.total" @click="offset+=30;run(load)">下一页学习集</button></nav>
<template v-if="current"><div class="grid cols-2"><label class="field">学习集标题<input v-model="form.title" maxlength="200"/></label><label class="field">学习笔记<textarea v-model="form.notes" maxlength="30000"/></label></div><div class="row"><button :disabled="busy||!dirty||!form.title.trim()" @click="run(save)">保存学习笔记</button><button :disabled="busy||!dirty" @click="bind(current)">放弃未保存说明</button><RouterLink v-if="current.collection_id" class="btn" :to="`/collections?id=${current.collection_id}`">打开通用收藏集</RouterLink><button @click="showHistory=!showHistory">{{showHistory?'收起':'查看'}}学习历史</button></div><VersionPanel v-if="showHistory" :key="current.id" kind="study" :entity-id="current.id" @restored="run(()=>select(current.id))"/>
<details><summary>添加已有素材为练习记录</summary><div class="grid"><label class="field">现有OC素材<select v-model="entry.reference_id"><option value="">请选择素材引用</option><option v-for="r in resources" :key="r.id" :value="r.id">{{r.title}} · {{r.role}}</option></select></label><div class="grid cols-2"><label class="field">练习类型<select v-model="entry.stage"><option v-for="(label,k) in stages" :key="k" :value="k">{{label}}</option></select></label><label class="field">学习日期<input v-model="entry.learned_on" type="date"/></label></div><label class="field">过程说明<textarea v-model="entry.notes" maxlength="10000"/></label><button :disabled="busy||dirty||!entry.reference_id" @click="run(append)">添加练习记录（引用原素材）</button></div></details>
<section class="entry-grid"><article v-for="e in visible" :key="e.id" class="card grid"><img v-if="e.is_image&&e.status==='ok'&&!e.historical_file" :src="thumb(e.entity_id)" :alt="e.title" loading="lazy"/><b>{{e.title}}</b><small>{{stages[e.stage]}} · {{e.learned_on}}</small><p>{{e.learning_notes}}</p><p v-if="e.status!=='ok'" class="notice">{{e.status}}</p><small v-if="e.historical_file">当前素材已有新版，此练习仍引用历史版本。</small><div class="row"><RouterLink class="btn" :to="`/assets?open=${e.entity_id}`">素材档案</RouterLink><button :disabled="busy||dirty" @click="edit(e)">编辑过程</button><button :disabled="busy||dirty" @click="run(()=>remove(e))">移除练习记录</button></div></article></section><nav class="row"><button :disabled="!entriesOffset" @click="entriesOffset-=50">前50项练习</button><span>{{current.entries.length}}项</span><button :disabled="entriesOffset+50>=current.entries.length" @click="entriesOffset+=50">后50项练习</button></nav>
<section v-if="editing" class="grid card"><b>修改练习过程</b><label class="field">练习类型<select v-model="editing.stage"><option v-for="(label,k) in stages" :key="k" :value="k">{{label}}</option></select></label><label class="field">学习日期<input v-model="editing.learned_on" type="date"/></label><label class="field">过程说明<textarea v-model="editing.notes" maxlength="10000"/></label><div class="row"><button :disabled="busy||dirty" @click="run(saveEntry)">保存练习过程</button><button @click="editing=null">取消编辑</button></div></section>
<details><summary>比较练习阶段</summary><div class="grid cols-2"><label class="field">左练习<select v-model="left"><option value="">选择图片</option><option v-for="e in studyImages" :key="e.id" :value="e.id">{{stages[e.stage]}} · {{e.title}} · {{e.id.slice(0,5)}}</option></select></label><label class="field">右练习<select v-model="right"><option value="">选择图片</option><option v-for="e in studyImages" :key="e.id" :value="e.id">{{stages[e.stage]}} · {{e.title}} · {{e.id.slice(0,5)}}</option></select></label></div><button :disabled="!left||!right" @click="showCompare=true">加载练习对比</button><ImageComparison v-if="showCompare&&left&&right" :left="studyMedia(left)" :right="studyMedia(right)" left-label="左练习图" right-label="右练习图"/></details>
</template></section>
<section class="card grid"><h2>线稿提取与图像导出</h2><p class="notice small">基础边缘提取输出栅格线稿，质量需要人工检查；不提供矢量线稿。透明底仅用于线条或保留原有透明通道，不自动去除原图背景。动画只处理首帧。原始文件保持不变。</p><label class="field">处理源图<select v-model="source"><option value="">选择一张图片</option><optgroup label="OC图片"><option v-for="r in images" :key="r.id" :value="'oc:'+r.id">{{r.title}} · {{r.role}}</option></optgroup><optgroup v-if="studyImages.length" label="当前练习历史图"><option v-for="e in studyImages" :key="e.id" :value="'entry:'+e.id">{{stages[e.stage]}} · {{e.title}}</option></optgroup></select></label><div class="grid cols-2"><label class="field">操作<select v-model="operation"><option value="lineart">提取独立栅格线稿PNG</option><option value="export">转换格式导出副本</option></select></label><label v-if="operation==='export'" class="field">导出格式<select v-model="format"><option value="png">PNG</option><option value="jpeg">JPEG</option><option value="webp">WebP</option></select></label><label class="field">背景<select v-model="background"><option value="white">白底</option><option value="transparent">透明底 / 保留透明</option></select></label></div><label v-if="current&&operation==='lineart'" class="row"><input v-model="addToStudy" type="checkbox"/>将派生线稿加入当前学习集</label><div class="row"><button class="primary" :disabled="busy||dirty||!chosen" @click="run(process)">执行图像处理</button><a v-if="original" class="btn" :href="original">下载无损原始文件</a></div><small class="muted">最多3200万像素/128MiB源图，后台共用有限队列；原件下载不解码。导出缓存保留最多7天/200份/512MiB，可重新生成；派生线稿归入素材库长期保存。JPEG/WebP转换可能有损。PNG是无损编码，转换仍可能调整色彩/元数据，需完全保留请下载原件。</small><JobProgress :job="job"/><a v-if="job?.status==='done'&&job.result?.download" class="btn primary" :href="job.result.download">下载导出副本</a><p v-if="job?.result?.notice" role="status">{{job.result.notice}}</p></section>
<section class="card grid"><div class="row"><h2>绘画处理历史</h2><button :disabled="busy" @click="run(load)">刷新处理历史</button></div><article v-for="j in history" :key="j.id" class="row"><span>{{j.title}} · {{j.status}}</span><button :disabled="busy" @click="run(()=>resume(j))">查看任务</button><button :disabled="busy||dirty||['queued','running'].includes(j.status)" @click="run(()=>retry(j))">载入处理配方</button></article><small>失败或取消可载入配方再次执行；不会覆盖原图。最多展示20个本OC任务，服务重启不自动重放。</small></section>
</div></template>
<style scoped>h2{margin:0}.entry-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:10px}.entry-grid img{width:100%;height:160px;object-fit:contain;background:var(--sunken)}article p{white-space:pre-wrap;overflow-wrap:anywhere;max-height:180px;overflow:auto;margin:0}.field{min-width:0}input[type=checkbox]{width:auto}@media(max-width:550px){.entry-grid{grid-template-columns:minmax(0,1fr)}}</style>
